import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def _edge_cost(G, s, t):
    """Cost of edge s->t, treating missing cost as expensive (avoid it)."""
    c = G[s][t].get("cost")
    return c if c is not None else 1e9


def _path_cost(G, path):
    """Total cost along a node path, tolerating missing edge costs."""
    return sum(_edge_cost(G, path[i], path[i + 1]) for i in range(len(path) - 1))


def _tree_path(tree, src, dst):
    """Unique path src -> dst in an undirected tree (BFS parent tracking)."""
    if src == dst:
        return [src]
    parents = {src: None}
    queue = [src]
    while queue:
        node = queue.pop(0)
        for nb in tree.neighbors(node):
            if nb not in parents:
                parents[nb] = node
                if nb == dst:
                    # reconstruct path
                    path = [dst]
                    while parents[path[-1]] is not None:
                        path.append(parents[path[-1]])
                    return path[::-1]
                queue.append(nb)
    return None


def search_algorithm(src, dsts, G, num_partitions):
    """
    Broadcast routing via Steiner-tree heuristic (shortest-path / metric-closure MST):
    1. One single-source Dijkstra from src gives shortest paths to all nodes.
    2. Build metric closure over terminals (src + dsts), take MST -> Steiner tree.
    3. For each dst, route along the tree (shared low-cost edges);
       fall back to its plain shortest path if the tree route costs more.
    This reduces redundant transfers and balances traffic on shared trunks.
    """
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    bc_topology = BroadCastTopology(src, dsts, num_partitions)

    # Single-source Dijkstra: shortest paths from src to everywhere (computed once).
    _, sp_paths = nx.single_source_dijkstra(h, src, weight="cost")

    # ---- Steiner tree via metric-closure MST (Kou et al. heuristic) ----
    terminals = [src] + list(dsts)
    closure = nx.Graph()
    closure.add_nodes_from(terminals)
    for i in range(len(terminals)):
        for j in range(i + 1, len(terminals)):
            a, b = terminals[i], terminals[j]
            pa = sp_paths.get(a)
            pb = sp_paths.get(b)
            # distance a<->b via shortest paths through src (upper bound)
            if pa is not None and b in pa:
                # b on path to a: a->b prefix
                idx = pa.index(b)
                d_ab = _path_cost(h, pa[: idx + 1])
            elif pb is not None and a in pb:
                # undirected approximation: use b->a path if a lies on it
                idx = pb.index(a)
                d_ab = _path_cost(h, pb[: idx + 1])
            else:
                try:
                    d_ab, _ = nx.bidirectional_dijkstra(h, a, b, weight="cost")
                except Exception:
                    d_ab = float("inf")
            if d_ab < float("inf"):
                closure.add_edge(a, b, weight=d_ab)

    steiner_tree = nx.Graph()
    if closure.number_of_edges() > 0:
        mst = nx.minimum_spanning_tree(closure, weight="weight")
        # Expand MST edges into underlying graph paths (directed src->dst paths).
        for a, b in mst.edges():
            pa = sp_paths.get(a)
            if pa is not None and b in pa:
                idx = pa.index(b)
                sub = pa[: idx + 1]
                for k in range(len(sub) - 1):
                    s, t = sub[k], sub[k + 1]
                    steiner_tree.add_edge(s, t)
            else:
                pb = sp_paths.get(b)
                if pb is not None and a in pb:
                    idx = pb.index(a)
                    sub = pb[: idx + 1]
                    for k in range(len(sub) - 1):
                        s, t = sub[k], sub[k + 1]
                        steiner_tree.add_edge(s, t)

    # ---- Route each dst: prefer tree path (shares edges), fallback to shortest ----
    chosen = {}
    for dst in dsts:
        best_path = sp_paths.get(dst)
        best_cost = _path_cost(h, best_path) if best_path else float("inf")
        if steiner_tree.number_of_edges() > 0 and dst in steiner_tree:
            tpath = _tree_path(steiner_tree, src, dst)
            # tree path is undirected; validate directed edges exist
            if tpath is not None and all(h.has_edge(tpath[k], tpath[k + 1]) for k in range(len(tpath) - 1)):
                tcost = _path_cost(h, tpath)
                # Use tree route if it is at least as good (ties -> tree, to share edges)
                if tcost <= best_cost:
                    best_path, best_cost = tpath, tcost
        if best_path is None:
            # last-resort: any path ignoring costs
            best_path = nx.shortestest_path(h, src, dst) if False else nx.dijkstra_path(h, src, dst, weight="cost")
        chosen[dst] = best_path

    for dst in dsts:
        path = chosen[dst]
        for i in range(len(path) - 1):
            s, t = path[i], path[i + 1]
            for j in range(bc_topology.num_partitions):
                bc_topology.append_dst_partition_path(dst, j, [s, t, G[s][t]])

    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


